package com.campus.trade.ai.dispute;
import org.springframework.stereotype.Component; import java.util.*;
@Component public class DisputeAgentValidator { public void validate(DisputeAgentResult x,Set<String> allowed,Map<String,Object> snapshot){ if(x==null||x.suggestedAction()==null||x.liability()==null)bad("action/liability不能为空"); if(x.confidence()==null||x.confidence()<0||x.confidence()>1)bad("confidence非法"); if(x.reasons()==null||x.reasons().size()>10||x.verifiedFacts()==null||x.verifiedFacts().size()>10||x.missingEvidence()==null||x.missingEvidence().size()>10||x.ruleRefs()==null||x.ruleRefs().size()>10)bad("数组数量非法"); for(var q:x.ruleRefs())if(q==null||q.ruleId()==null||q.ruleVersion()==null||!allowed.contains(q.ruleId()+"@"+q.ruleVersion()))bad("规则引用非法"); for(var q:x.verifiedFacts())if(q==null||q.field()==null||q.quote()==null||!String.valueOf(snapshot.getOrDefault(q.field(),"")).contains(q.quote()))bad("原文事实不存在"); if((x.suggestedAction()==DisputeAgentAction.REJECT||x.suggestedAction()==DisputeAgentAction.CANCEL_TRADE)&&(x.ruleRefs().isEmpty()||x.verifiedFacts().isEmpty()))bad("定责建议缺少依据"); if(x.suggestedAction()==DisputeAgentAction.NEED_MORE&&x.missingEvidence().isEmpty())bad("补充材料建议缺少清单"); } private void bad(String s){throw new DisputeAgentOutputInvalidException(s);} }
